code='''def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # Fill interiors of rectangular frames, preserving their borders.
    for color in set(v for row in g for v in row):
        pts=[(r,c) for r in range(h) for c in range(w) if g[r][c]==color]
        if not pts: continue
        r0=min(r for r,c in pts); r1=max(r for r,c in pts)
        c0=min(c for r,c in pts); c1=max(c for r,c in pts)
        if r1-r0>=2 and c1-c0>=2 and all(g[r0][c]==color and g[r1][c]==color for c in range(c0,c1+1)) and all(g[r][c0]==color and g[r][c1]==color for r in range(r0,r1+1)):
            for r in range(r0+1,r1):
                for c in range(c0+1,c1):
                    g[r][c]=2
    # A 3x3 ring marker gets its center changed to 7.
    for r in range(h-2):
        for c in range(w-2):
            vals=[g[r+i][c+j] for i in range(3) for j in range(3)]
            ring=[vals[i] for i in range(9) if i!=4]
            if len(set(ring))==1 and ring[0] not in (2,):
                if vals[4] != ring[0]: g[r+1][c+1]=7
    return g
'''
